    facts:[["Prime minister","Aneurin Bevan"],["Took office","November 1947"],["Left office","October 1951"],["Party","Reconstruction Labour"],["Seats held","218 of 640"],["Form","Minority ministry"],["Legislature","Brick Parliament"],["End","Budget defeat and dissolution"]]
